<?php
namespace App\Models;use Illuminate\Database\Eloquent\{Model,SoftDeletes};class TrainingNeed extends Model{use SoftDeletes;protected $fillable=['company_id','code','title','description','origin_type','origin_description','priority','identified_at','required_by','target_population_type','target_population_description','status','identified_by','created_by','updated_by'];protected $casts=['identified_at'=>'date','required_by'=>'date'];public function company(){return$this->belongsTo(PerfilEmpresa::class,'company_id');}public function risks(){return$this->belongsToMany(MatrizRiesgo::class,'training_need_risk');}public function programItems(){return$this->belongsToMany(TrainingProgramItem::class,'training_need_program_item');}public function scopeForCompany($q,int$id){return$q->where('company_id',$id);}public function scopePendingPlanning($q){return$q->whereIn('status',['approved','evaluated'])->whereDoesntHave('programItems');}}
